import{_ as p,a0 as r,w as s,s as x,ao as a,I as e,a1 as l,A as u,x as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const D=JSON.parse('{"title":"適合新用户的最佳的Linux發行版 | LCTT x X-CMD","titleTemplate":false,"description":"適合新用户的最佳的Linux發行版 | LCTT (201407) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"適合新用户的最佳的Linux發行版 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"適合新用户的最佳的Linux發行版 | LCTT (201407) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201407/20140610 The Best Linux Distribution for New Users","title":"適合新用户的最佳的Linux發行版","tag":"201407","desc":""},"relativePath":"201407/20140610 The Best Linux Distribution for New Users.md","filePath":"[post].md"}'),o={name:"201407/20140610 The Best Linux Distribution for New Users.md"};function d(h,i,L,b,m,f){const t=r("Link");return s(),x("div",null,[i[19]||(i[19]=a('<h1 id="適合新用户的最佳的linux發行版" tabindex="-1">適合新用户的最佳的Linux發行版 <a class="header-anchor" href="#適合新用户的最佳的linux發行版" aria-label="Permalink to “適合新用户的最佳的Linux發行版”">​</a></h1><p>這個爭論無疑給許多Linux用户帶來了麻煩。爭論的焦點一般不是哪個發行版是真正最適合新用户的，而是哪個發行版受這些爭論者的喜愛。如果我們撇開個人喜愛，我們會看到更清楚的一面。但即使這樣，明確的結論也會受到被新用户的需求和期望的影響。考慮到這點，我決定採取一個不同的方法來找出“對新用户來説最好的發行版”。我評判最好發行版的標準不僅是易用，而且還要具有由日益增長的移動界面風格所帶來的現代設計理念。</p><p>對於這次評測，我們對發行版有如下要求：</p><ul><li>非常友好</li><li>包括，開箱即用，所有常用的應用程序</li><li>包括某個形式的應用程序商店</li><li>提供一個時尚的用户界面</li></ul><p>讓我解釋一下各個標準</p><h3 id="用户友好" tabindex="-1">用户友好 <a class="header-anchor" href="#用户友好" aria-label="Permalink to “用户友好”">​</a></h3><p>這是一個備受爭議的話題。但事實的真相是——新用户必須能夠選擇某種風格的Linux並開始使用，只需要很少或不需要解釋。如果必須很出太多解釋，那麼這個發行版便不是用户友好的。我不喜歡那些操作系統，但是幾乎任何用户都可以在近乎零指導的情況下坐在Windows 7或OS X桌面前並開始使用它。這是每一個Linux桌面都應當爭取去做的。</p><h3 id="常用應用程序" tabindex="-1">常用應用程序 <a class="header-anchor" href="#常用應用程序" aria-label="Permalink to “常用應用程序”">​</a></h3><p>安裝好系統後用户不應該再去安裝必需的程序。那麼什麼是必需的呢？每年列表都會變短。目前，必備的程序列表如下：</p><ul><li>網頁瀏覽器：Chrome或者Firefox（對不起，根本不需要其他的瀏覽器）</li><li>電子郵件客户端：Thunderbird是顯而易見的選擇。</li><li>Office辦公套件：LibreOffice。就這樣。</li><li>音樂播放器：播放本地文件以及連接到流媒體服務（比如Spotify）。</li></ul><p>這是幾乎所有用户需要的應用程序的簡表。</p><h3 id="應用程序商店" tabindex="-1">應用程序商店 <a class="header-anchor" href="#應用程序商店" aria-label="Permalink to “應用程序商店”">​</a></h3><p>由於移動設備需求的日益增長，用户已經習慣了應用商店。Linux有應用商店很長時間了（Synaptic是最古老的一個）。沒有一個經深思熟慮做的應用商店，用户將會掙扎於在Linux環境中添加軟件。毫無疑問，這一點至關重要。</p><h3 id="時尚的界面" tabindex="-1">時尚的界面 <a class="header-anchor" href="#時尚的界面" aria-label="Permalink to “時尚的界面”">​</a></h3><p>我已經多次提到移動設備的美化。由於iOS和Android，用户越來越喜歡時尚的界面。Linux的桌面需要進行效仿並且用獨特的、時尚的和易用的界面來吸引用户注意力。舊的風格在支持多觸控的移動世界裏不再有影響力。</p><h2 id="排名前三的發行版" tabindex="-1">排名前三的發行版 <a class="header-anchor" href="#排名前三的發行版" aria-label="Permalink to “排名前三的發行版”">​</a></h2><p>以文中的標準，哪個發行版本滿足了（或超過）我們的需求？首先，讓我們來審查一下前三名的候選者。以下哪個滿足了（或超過）標準。</p><h3 id="ubuntu" tabindex="-1">Ubuntu <a class="header-anchor" href="#ubuntu" aria-label="Permalink to “Ubuntu”">​</a></h3>',18)),e("p",null,[l(t,{href:"http://www.ubuntu.com/"},{default:u(()=>[...i[0]||(i[0]=[n("Ubuntu Linux",-1)])]),_:1}),i[1]||(i[1]=n("一直是用户友好型Linux的王者。開箱即用，尋找一個比它更迷人和易用的桌面（Unity）有點困難，甚至是對於那些對平台不熟悉的人也是這樣的。它的桌面佈局雖然與眾不同，但卻是合乎邏輯和很直觀的。對於在桌面環境中添加一個最強大的搜索工具，在Linux中Ubuntu Unity應當獲得最高成就。",-1))]),i[20]||(i[20]=e("h3",{id:"linux-mint",tabindex:"-1"},[n("Linux Mint "),e("a",{class:"header-anchor",href:"#linux-mint","aria-label":"Permalink to “Linux Mint”"},"​")],-1)),e("p",null,[i[3]||(i[3]=n("如果認為有一個篡奪王位的發行版，那它就是",-1)),l(t,{href:"http://www.linuxmint.com/"},{default:u(()=>[...i[2]||(i[2]=[n("Linux Mint",-1)])]),_:1}),i[4]||(i[4]=n("。Linux Mint做了更多桌面的標準方法，但是圖層華麗且多變使其從老舊的桌面隱喻中脱穎而出。Linux Mint基於Ubuntu，所以它得益於“老大哥”Ubuntu的穩定性和可靠性。",-1))]),i[21]||(i[21]=e("h3",{id:"linux-deepin",tabindex:"-1"},[n("Linux Deepin "),e("a",{class:"header-anchor",href:"#linux-deepin","aria-label":"Permalink to “Linux Deepin”"},"​")],-1)),e("p",null,[i[6]||(i[6]=n("用户友好型列表中的新成員是",-1)),l(t,{href:"http://www.linuxdeepin.com/index.en.html"},{default:u(()=>[...i[5]||(i[5]=[n("Linux Deepin",-1)])]),_:1}),i[7]||(i[7]=n("。這個相對較新的受歡迎的發行版來自中國，而且應該正視它所帶來的成就。為什麼這樣説？因為它使得Linux桌面轉變為藝術美；同時也保持了高水平的用户友好性。我期待它的新版本發佈將是個大事件。Linux Deepin使用的是GNOME 3桌面並將它重組得完全不同的，完全不可思議。",-1))]),i[22]||(i[22]=a('<h2 id="各發行版的比分" tabindex="-1">各發行版的比分 <a class="header-anchor" href="#各發行版的比分" aria-label="Permalink to “各發行版的比分”">​</a></h2><p>在最佳的競爭者名單中，我們來比較一下每一個標準和等級。每個發行版的比分如下：對於每個標準，發行版排名從高到底（第一名得一分，最後一名得三分）。最後，總分決定誰是冠軍——最低得分獲勝。</p><h3 id="用户友好性" tabindex="-1">用户友好性 <a class="header-anchor" href="#用户友好性" aria-label="Permalink to “用户友好性”">​</a></h3><p>這可能是最嚴密的分類和最艱難的判別。每個發行版以不同的方法在用户友好性上都各有優勢。最後，我的排名是：</p><ol><li><p>Linux Mint</p></li><li><p>Ubuntu Linux</p></li><li><p>Linux Deepin</p></li></ol><p>為什麼是這樣呢？Mint僅有微小的優勢，因為它的開始按鈕，任務欄和桌面圖標仍然使用舊的桌面風格。勝者的優勢很微小，Ubuntu和Linux Deepin要求的學習曲線近乎為零——甚至是對於小白們。</p><h3 id="常用的應用程序" tabindex="-1">常用的應用程序 <a class="header-anchor" href="#常用的應用程序" aria-label="Permalink to “常用的應用程序”">​</a></h3><p>這一類別難以判斷的唯一原因是因為每個發行版都包括所有必要的應用程序。雖然Linux Deepin目前提供的是金山Office（一個最好的移動辦公套件解決方案之一），它計劃在2014發行版本中默認使用LibreOffice。</p><p>關於常用程序的我的一個問題是音樂播放器。雖然我在線聽過很多音樂（使用Spotify客户端），但當我播放本地音樂時，總是使用Clementine。他們的默認播放器是：</p><ul><li>Ubuntu: Rhythmbox</li><li>Linux Mint: Banshee</li><li>Linux Deepen: DMusic.</li></ul><p>三者中，Banshee（圖1）提供了最多的功能，DMusic（圖2）提供了最好的界面，（令人驚訝的）Rhythmbox（圖3）目前最不穩定。</p><p><img src="http://www.linux.com/images/stories/41373/banshee.png" alt=""></p><p>banshee</p><p><img src="http://www.linux.com/images/stories/41373/dmusic.png" alt=""></p><p>dmusic</p><p><img src="http://www.linux.com/images/stories/41373/rhythmbox.png" alt=""></p><p>rhythmbox</p><p>所以，他們得分多少？如下：</p><ol><li><p>Linux Mint</p></li><li><p>Ubuntu Linux</p></li><li><p>Linux Deepin</p></li></ol><h3 id="應用程序商店-1" tabindex="-1">應用程序商店 <a class="header-anchor" href="#應用程序商店-1" aria-label="Permalink to “應用程序商店”">​</a></h3><p>如果不分析這部分將難進行。為什麼呢？因為對於新用户應用商店可以輕易成就或是毀掉一個Linux發行版。總會有應用需求而且沒有用户想經過命令列的重重考驗。每個發行版都有自己的應用商店。</p><ul><li>Ubuntu: Ubuntu軟件中心</li><li>Mint: 軟件管理器</li><li>Linux Deepin: Deepin軟件中心</li></ul><p>應該説，這些工具中的每一個都是基於Ubuntu軟件中心的。奇怪的是Ubuntu軟件中心卻正好排在最底。主要原因是Ubuntu軟件中心太慢了——甚至在一個非常強大的機器上。</p><p>我將應用商店排名設為如下：</p><ol><li><p>Linux Deepin</p></li><li><p>Linux Mint</p></li><li><p>Ubuntu Linux</p></li></ol><p>每個應用商店有非常相似的功能。Linux Deepin獲得第一的原因有兩個：界面易於控制而且程序開啓速度遠遠快於Ubuntu軟件中心和Mint軟件管理器。</p><h3 id="時尚的界面-1" tabindex="-1">時尚的界面 <a class="header-anchor" href="#時尚的界面-1" aria-label="Permalink to “時尚的界面”">​</a></h3><p>在這部分Linux Mint遠遠落後。儘管它提供了一個華美的界面和有很淺的學習曲線，但相比之下它仍然是一個非常過時的桌面。甚至在強大的硬件（有強大的顯卡）上，Linux Mint仍然很容易被看成是來自90年代末的桌面。為了評判結果，我們必須看看是Ubuntu Linux還是Linux Deepin能帶我們走進未來。勝者是：</p><ol><li><p>Linux Deepin</p></li><li><p>Ubuntu Linux</p></li><li><p>Linux Mint</p></li></ol><p>Linux Deepin使用GNOME 3來製作一個使用起來很漂亮的GNOME和OSX的混合體，你會認為你在處理一件互動的藝術品。</p><h2 id="總冠軍" tabindex="-1">總冠軍 <a class="header-anchor" href="#總冠軍" aria-label="Permalink to “總冠軍”">​</a></h2><p>雖然這是很初步的，對新用户來説最好的Linux發行版順序應該是：</p><ol><li><p>Linux Mint的總得分是7</p></li><li><p>Linux Deepin的總得分是8</p></li><li><p>Ubuntu Linux的總得分是9</p></li></ol><p>如果你想知道關於這篇文章的作者觀點，要知道：我已經使用Ubuntu Linux很多年了（而且仍在用）。我最近一直在説“如果有一個Linux發行版能動搖我使用Ubuntu的想法，它便是Linux Deepin。”雖然我很欣賞Linux Mint，但我只是用它來進行測試。當説到對新用户最好的Linux發行版，Linux Mint是顯而易見的贏家。</p><p>這件事真正的真相是——你在使用這些桌面中任何一個都不會錯。他們都各有所長。如果你追求真正的美麗，使用Linux Deepin吧。如果你想要漂亮外觀與易用結合，那就使用Ubuntu Linux。如果你只想要簡單而且並不在乎漂亮的外觀，那就用Linux Mint。不管你選哪一個，這都是三贏的局面。</p><p>你怎麼認為？你會如何排這三個桌面的名次？或者，你是否會寫一個不同的Linux發行版，該發行版在外表上來説對新用户最好的？（還有原因是什麼？）</p><hr>',37)),e("p",null,[i[9]||(i[9]=n("via: ",-1)),l(t,{href:"http://www.linux.com/news/software/applications/775873-the-best-linux-distribution-for-new-users/"},{default:u(()=>[...i[8]||(i[8]=[n("http://www.linux.com/news/software/applications/775873-the-best-linux-distribution-for-new-users/",-1)])]),_:1})]),e("p",null,[i[12]||(i[12]=n("譯者：",-1)),l(t,{href:"https://github.com/linuhap"},{default:u(()=>[...i[10]||(i[10]=[n("linuhap",-1)])]),_:1}),i[13]||(i[13]=n(" 校對：",-1)),l(t,{href:"https://github.com/wxy"},{default:u(()=>[...i[11]||(i[11]=[n("wxy",-1)])]),_:1})]),e("p",null,[i[16]||(i[16]=n("本文由 ",-1)),l(t,{href:"https://github.com/LCTT/TranslateProject"},{default:u(()=>[...i[14]||(i[14]=[n("LCTT",-1)])]),_:1}),i[17]||(i[17]=n(" 原創翻譯，",-1)),l(t,{href:"http://linux.cn/"},{default:u(()=>[...i[15]||(i[15]=[n("Linux中國",-1)])]),_:1}),i[18]||(i[18]=n(" 榮譽推出",-1))])])}const U=p(o,[["render",d]]);export{D as __pageData,U as default};
